import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * TASK: Complete SeatBookingIndex. The SeatKey record above it is provided --
 * do not edit it.
 *
 * Seats are identified by a row letter plus a number, so a record makes a
 * perfect map key: two SeatKey values with the same row and number are equal
 * and hash the same, even though they are different objects.
 *
 * - book(row, number, passenger) stores the booking and returns true. If that
 *   seat is already booked it changes nothing and returns false.
 * - passengerAt(row, number) returns the passenger name, or null when the seat
 *   is free.
 * - isBooked(row, number) reports whether the seat is taken.
 * - bookedCount() is how many seats are booked in total.
 * - passengersInRow(row) lists the passengers in that row, sorted
 *   alphabetically. An unused row gives an empty list.
 *
 * Example: book('A', 1, "ana") then passengerAt('A', 1) -> "ana", and a second
 * book('A', 1, "bo") returns false.
 */
record SeatKey(char row, int number) { }

public class SeatBookingIndex {

    private final Map<SeatKey, String> bookings = new HashMap<>();

    public boolean book(char row, int number, String passenger) {
        SeatKey key = new SeatKey(row, number);
        if (bookings.containsKey(key)) {
            return false;
        }
        bookings.put(key, passenger);
        return true;
    }

    public String passengerAt(char row, int number) {
        return bookings.get(new SeatKey(row, number));
    }

    public boolean isBooked(char row, int number) {
        return bookings.containsKey(new SeatKey(row, number));
    }

    public int bookedCount() {
        return bookings.size();
    }

    public List<String> passengersInRow(char row) {
        List<String> names = new ArrayList<>();
        for (Map.Entry<SeatKey, String> entry : bookings.entrySet()) {
            if (entry.getKey().row() == row) {
                names.add(entry.getValue());
            }
        }
        Collections.sort(names);
        return names;
    }
}
